CREATE OR REPLACE PROCEDURE calculate_employee_bonus(
    emp_id INT,
    salary NUMERIC,
    performance_rating INT
)
LANGUAGE plpgsql
AS $$
DECLARE
    bonus_multiplier NUMERIC;
    final_bonus NUMERIC;
BEGIN
    -- 1. Determine multiplier based on rating (Step here)
    IF performance_rating >= 5 THEN
        bonus_multiplier := 0.20;
    ELSIF performance_rating >= 3 THEN
        bonus_multiplier := 0.10;
    ELSE
        bonus_multiplier := 0.05;
    END IF;

    -- 2. Calculate the final bonus (Step again)
    final_bonus := salary * bonus_multiplier;

    -- 3. Update the record
    UPDATE employees 
    SET last_bonus = final_bonus, 
        last_updated = NOW() 
    WHERE id = emp_id;

    -- 4. Final check
    RAISE NOTICE 'Bonus of % calculated for Employee %', final_bonus, emp_id;
END;
$$
